local empty_sprite = {filename = "__core__/graphics/empty.png", width = 1, height = 1}

-- Generated by tools/sprites/render.mjs from tools/sprites/models/warp-drive.js; each sheet has a
-- matching .lua file with the width, height, shift, and line_length util.sprite_load reads.
local sprite_path = "__bte-warp-drive__/graphics/entity/warp-drive/warp-drive-"

local function sprite_layer(name, options)
  options = options or {}
  options.scale = 0.5
  return util.sprite_load(sprite_path .. name, options)
end

local function empty_directional_sprites()
  return {
    north = empty_sprite,
    east = empty_sprite,
    south = empty_sprite,
    west = empty_sprite
  }
end

-- The static hull and its shadow. Everything that moves is drawn over it: status lamps by the
-- animation companion, and the per-state core overlays by scripts/visuals.lua.
local function hull_sprite()
  return {
    layers = {
      sprite_layer("main"),
      sprite_layer("shadow", {draw_as_shadow = true})
    }
  }
end

local function hull_directional_sprites()
  local sprite = hull_sprite()
  return {
    north = sprite,
    east = table.deepcopy(sprite),
    south = table.deepcopy(sprite),
    west = table.deepcopy(sprite)
  }
end

-- The insulator tips of the circuit terminal south-west of the dais, red east of green.
local function drive_wire_connection_points()
  local point = {
    wire = {red = {-1.45, 2.93}, green = {-1.65, 2.93}},
    shadow = {red = {-0.47, 4.0}, green = {-0.67, 4.0}}
  }
  local points = {}
  for index = 1, 4 do
    points[index] = table.deepcopy(point)
  end
  return points
end

local function glow_layer(name, options)
  options = options or {}
  options.blend_mode = "additive"
  options.draw_as_glow = true
  return sprite_layer(name, options)
end

-- One animation prototype per state overlay, drawn with LuaRendering.draw_animation, which sets
-- the playback speed itself. Frame counts match the model's layers: static interiors where the
-- rings are still, 32-frame loops, and the 30-frame activation pulse.
local overlay_frames = {
  standby = {interior = 1, glow = 32},
  charging = {interior = 32, glow = 32},
  activation = {interior = 30, glow = 30},
  warp = {interior = 1, glow = 32}
}
local overlays = {}
for state, frames in pairs(overlay_frames) do
  overlays[#overlays + 1] = {
    type = "animation",
    name = "bte-warp-drive-" .. state .. "-interior",
    layers = {sprite_layer("interior-" .. state, {frame_count = frames.interior})}
  }
  overlays[#overlays + 1] = {
    type = "animation",
    name = "bte-warp-drive-" .. state .. "-glow",
    layers = {glow_layer("glow-" .. state, {frame_count = frames.glow})}
  }
end

